import 'dart:typed_data';

import 'package:pdf/pdf.dart';

/// App settings that change how a layout renders (not part of the layout).
class TemplateOptions {
  final String currencySymbol;

  /// Thousands grouping: 'none' | 'international' | 'indian'.
  final String amountSeparator;
  final String datePattern;

  /// '12' (2:30 PM) or '24' (14:30) for `{{invoice.datetime}}`.
  final String timeFormat;
  final bool showGst;
  final bool showAliasName;
  final bool showDescription;
  final String signaturePosition;
  final double signatureSizePx;

  /// App-owned "Generated by Invoiso" footer; a layout cannot override it.
  final bool showFooterBranding;
  final double footerFontSize;
  final String thankYouNote;

  /// Accent used when the layout document has no `theme.primary`.
  final PdfColor? themeColor;

  const TemplateOptions({
    this.currencySymbol = '',
    this.amountSeparator = 'none',
    this.datePattern = 'dd/MM/yyyy',
    this.timeFormat = '24',
    this.showGst = true,
    this.showAliasName = false,
    this.showDescription = false,
    this.signaturePosition = 'left',
    this.signatureSizePx = 50,
    this.showFooterBranding = true,
    this.footerFontSize = 8,
    this.thankYouNote = '',
    this.themeColor,
  });
}

/// Images a layout can place (logo, signature).
class TemplateAssets {
  final Uint8List? logo;
  final Uint8List? signature;

  const TemplateAssets({this.logo, this.signature});
}
